function escapeRegex(s) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function extractSection(markdown, headingText) {
  // Headings must match whole line at start, per handbook.
  const headingRe = new RegExp(`^##\\s+${escapeRegex(headingText)}\\s*$`, "m");
  const m = markdown.match(headingRe);
  if (!m || m.index == null) return "";
  const startIdx = m.index;
  const afterHeadingIdx = startIdx + m[0].length;

  // Find next level-2 heading
  const rest = markdown.slice(afterHeadingIdx);
  const nextRe = /^##\s+.+\s*$/m;
  const next = rest.match(nextRe);
  const endIdx = next && next.index != null ? afterHeadingIdx + next.index : markdown.length;
  return markdown.slice(startIdx, endIdx);
}

function parseArchive(markdown) {
  const meetingsSection = extractSection(markdown, "Meeting Notes");
  const emailsSection = extractSection(markdown, "Email Excerpts");
  const policySection = extractSection(markdown, "Policy Exceptions");
  const correctionsSection = extractSection(markdown, "Correction Notices");
  const ledgerSection = extractSection(markdown, "Transaction Ledger");

  return {
    ledger: parseLedger(ledgerSection),
    meetings: parseMeetings(meetingsSection),
    emails: parseEmails(emailsSection),
    corrections: parseCorrections(correctionsSection),
    policyExceptions: parsePolicyExceptions(policySection),
  };
}

module.exports = { parseArchive, extractSection };
EOF

