function parseLedger(ledgerSectionMarkdown) {
  if (!ledgerSectionMarkdown) return [];

  // The ledger section contains one or more ledger blocks as ### <TXN-id>
  // Keep the last non-provisional block in file order for each id.
  const byId = new Map();
  const blocks = ledgerSectionMarkdown.split(/^###\s+/m).slice(1);

