function parseMeetings(meetingsSectionMarkdown) {
  if (!meetingsSectionMarkdown) return [];

  const amendments = [];

  // Capture each amendment block bounded by next #### heading (or end of section)
  const re = /^####\s+Amendment for\s+(TXN-[0-9a-f-]+)\s*$/gim;
  let match;
  while ((match = re.exec(meetingsSectionMarkdown)) !== null) {
    const start = match.index;
    const afterHeading = start + match[0].length;
    const rest = meetingsSectionMarkdown.slice(afterHeading);
    const next = rest.match(/^####\s+/m);
    const end = next && next.index != null ? afterHeading + next.index : meetingsSectionMarkdown.length;
    const block = meetingsSectionMarkdown.slice(start, end);

    const ownerMatch = block.match(/^owner:\s*(.+)$/im);
    const signedMatch = block.match(/^signed:\s*(.+)$/im);
    const effectiveMatch = block.match(/^effective:\s*(\d{4}-\d{2}-\d{2})\s*$/im);

    amendments.push({
      transaction_id: match[1],
      owner: ownerMatch ? ownerMatch[1].trim() : "",
      signed: signedMatch ? String(signedMatch[1]).trim().toLowerCase() === "true" : false,
      effective: effectiveMatch ? effectiveMatch[1].trim() : null,
    });
  }

