const { sortByTransactionId, sortByNoticeId } = require("../utils/sort");

const STATUS_ORDER = {
  pending: 0,
  approved: 1,
  rejected: 2,
  reversed: 3,
};

function statusRank(s) {
  const key = String(s || "").toLowerCase();
  return Object.prototype.hasOwnProperty.call(STATUS_ORDER, key)
    ? STATUS_ORDER[key]
    : -1;
}

function reconcileTransactions(parsed) {
  const ledgerRows = Array.isArray(parsed.ledger) ? parsed.ledger : [];
  const emails = Array.isArray(parsed.emails) ? parsed.emails : [];
  const meetings = Array.isArray(parsed.meetings) ? parsed.meetings : [];
  const corrections = Array.isArray(parsed.corrections) ? parsed.corrections : [];

  // Base rows from ledger
  const byId = new Map();
  for (const row of ledgerRows) {
    if (!row || !row.transaction_id) continue;
    byId.set(row.transaction_id, {
      transaction_id: row.transaction_id,
      owner: row.owner || "",
      status: String(row.status || "").toLowerCase(),
      date: row.date || "",
      amount: Number(row.amount),
      // metadata for exception computation
      _ledger_date: row.date || "",
      _qualifying_compliance_email_with_sent: false,
      _policy_waiver_eligible: false,
      _winning_status_correction_applied: false,
      _effective_date_override: null,
    });
  }

  // Meeting amendments: replace owner when signed:true (case-insensitive)
  // and (effective missing OR effective >= ledger date)
  for (const amend of meetings) {
    if (!amend || !amend.transaction_id) continue;
    const target = byId.get(amend.transaction_id);
    if (!target) continue;
    if (!amend.signed) continue;
    if (amend.effective && target._ledger_date && amend.effective < target._ledger_date) {
      continue;
    }
    if (amend.owner) target.owner = amend.owner;
  }

  // Emails: may change status only when From contains compliance@
  // If sent present, only apply if sent >= ledger date.
  // If no sent, apply only if precedence allows (new >= current)
  for (const email of emails) {
    if (!email || !email.transaction_id) continue;
    const target = byId.get(email.transaction_id);
    if (!target) continue;

    const from = String(email.from_addr || "").toLowerCase();
    if (!from.includes("compliance@")) continue;

    const newStatus = String(email.status || "").toLowerCase();
    if (statusRank(newStatus) < 0) continue;

    if (email.sent) {
      if (target._ledger_date && email.sent < target._ledger_date) {
        continue;
      }
      // sent present: apply regardless of precedence (handbook: apply status change only if sent>=ledger date)
      target.status = newStatus;
      target._qualifying_compliance_email_with_sent = true;
    } else {
      if (statusRank(newStatus) >= statusRank(target.status)) {
        target.status = newStatus;
      }
    }
  }

  // Policy exception IDs passed through for later (exception_reason computation)
  const policyIds = parsed.policyExceptions instanceof Set ? parsed.policyExceptions : new Set();
  for (const id of policyIds) {
    const target = byId.get(id);
    if (target) target._policy_waiver_eligible = true;
  }

  // Correction notices: winning per (transaction, field) is lexicographically greatest effective date.
  const winnersByKey = new Map();
  for (const notice of corrections) {
    if (!notice || !notice.transaction_id || !notice.field || !notice.effective) continue;
    const key = `${notice.transaction_id}::${notice.field}`;
    const prev = winnersByKey.get(key);
    if (!prev || String(notice.effective) > String(prev.effective)) {
      winnersByKey.set(key, notice);
    }
  }

  const winningNotices = [...winnersByKey.values()];

  // Apply winning notices in increasing effective then notice_id to make previous_value meaningful deterministically
  winningNotices.sort((a, b) => {
    if (a.effective === b.effective) {
      if (a.notice_id === b.notice_id) return 0;
      return a.notice_id < b.notice_id ? -1 : 1;
    }
    return a.effective < b.effective ? -1 : 1;
  });

  const report = [];
  for (const notice of winningNotices) {
    const target = byId.get(notice.transaction_id);
    if (!target) continue;

    const field = String(notice.field).trim();
    let previousValue = "";
    let applied = false;

    if (field === "owner") {
      previousValue = target.owner;
      target.owner = notice.value;
      applied = true;
    } else if (field === "status") {
      previousValue = target.status;
      target.status = String(notice.value || "").toLowerCase();
      target._winning_status_correction_applied = true;
      target._effective_date_override = notice.effective;
      applied = true;
    } else if (field === "date") {
      previousValue = target.date;
      target.date = notice.value;
      target._effective_date_override = notice.effective;
      applied = true;
    }

    if (applied) {
      report.push({
        notice_id: notice.notice_id,
        transaction_id: notice.transaction_id,
        field,
        previous_value: previousValue,
        new_value: notice.value,
        effective: notice.effective,
      });
    }
  }

  // Build final items
  const items = sortByTransactionId(
    [...byId.values()].map((row) => {
      const effectiveDate = row._effective_date_override
        ? row._effective_date_override
        : row._ledger_date;
      return {
        transaction_id: row.transaction_id,
        owner: row.owner,
        status: String(row.status).toLowerCase(),
        effective_date: effectiveDate,
        amount_usd: Number(Number(row.amount).toFixed(2)),
        exception_reason: null,
        // internal metadata used by exceptions builder
        _meta: {
          ledger_date: row._ledger_date,
          qualifying_compliance_email_with_sent: row._qualifying_compliance_email_with_sent,
          policy_waiver_eligible: row._policy_waiver_eligible,
          winning_status_correction_applied: row._winning_status_correction_applied,
        },
      };
    }),
  );

  // Report must be sorted by notice_id ascending
  sortByNoticeId(report);

  return { items, report };
}

module.exports = { reconcileTransactions, STATUS_ORDER, statusRank };
