function buildExceptionReason(row) {
  const reasons = [];
  const amount = Number(row.amount_usd);
  const status = String(row.status || "").toLowerCase();
  const meta = row._meta || {};

  if (Number.isFinite(amount) && amount > 10000) {
    reasons.push("over_limit");
  }

  if (
    status === "rejected" &&
    meta.qualifying_compliance_email_with_sent
  ) {
    reasons.push("compliance_hold");
  }

  if (
    status === "approved" &&
    Number.isFinite(amount) &&
    amount > 10000 &&
    meta.policy_waiver_eligible
  ) {
    reasons.push("policy_waiver");
  }

  if (
    status === "reversed" &&
    Number.isFinite(amount) &&
    amount > 5000 &&
    meta.winning_status_correction_applied
  ) {
    reasons.push("retroactive_review");
  }

  if (reasons.length === 0) return null;
  reasons.sort();
  return reasons.join(";");
}

function buildExceptions(items) {
  for (const row of items) {
    row.exception_reason = buildExceptionReason(row);
    // strip internal meta before output filtering
    delete row._meta;
  }
  return items.filter((row) => row.exception_reason);
}

module.exports = { buildExceptions };
